// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address target;

    function setUp() public {
        c = new SimpleWallet();
        target = address(0xBEEF);
    }

    function testFuzz_property(uint256 funded, uint256 value, address actor) public {
        funded = bound(funded, 0, 1e30);
        value = bound(value, 0, 1e30);
        vm.assume(actor != address(0));

        // fund the contract
        vm.deal(address(c), funded);

        // owner (deployer = this test contract) requests a payout of `value`
        vm.prank(address(this));
        c.sendMoney(target, value);

        uint256 remaining = address(c).balance;
        uint256 expected = value <= funded ? funded - value : funded;
        assertTrue(remaining == expected);
    }
}
